insert into public.landing_sections (kind, icon, title, body, sort_order) values
('hero', null, 'להגיע ללידה רגועה, בטוחה ומוכנה', 'קורס הכנה ללידה וליווי דולה אישי – ידע מעשי, כלים להתמודדות וחיבוק תומך, מההריון ועד אחרי הלידה.', 0),
('about', null, 'נעים להכיר, רחל לאה סגל', E'אני דולה ומדריכת הכנה ללידה. אני מאמינה שכל יולדת ראויה להגיע ללידה עם ידע, ביטחון ותמיכה – כדי שתוכל לבחור, להרגיש ולהיות נוכחת בחוויה שלה.\n\nבקורס ובליווי אני משלבת מידע מבוסס, תרגול מעשי של נשימות ותנוחות, הכנה של בן/בת הזוג, ותשומת לב אישית לצרכים ולחששות של כל אחת.', 1),
('service', 'book', 'קורס הכנה ללידה', 'מפגשים מעשיים (פרונטלי או דיגיטלי) + גישה מלאה לאזור התכנים באתר: שיעורים, סרטונים ודפי עבודה.', 10),
('service', 'heart', 'ליווי לידה – דולה', 'פגישות הכנה אישיות, זמינות טלפונית מסביב לשעון מהשבוע ה-38 ונוכחות רציפה לצידך בלידה עצמה.', 11),
('service', 'message', 'התייעצות אישית', 'שיחה ממוקדת לשאלות, חששות, בניית תכנית לידה או עיבוד לידה קודמת.', 12),
('topic', 'sparkles', 'שלבי הלידה', 'מה קורה בגוף בכל שלב, מתי לנסוע לבית החולים ומה מצפה לך בחדר הלידה.', 20),
('topic', 'wind', 'נשימות והרפיה', 'טכניקות נשימה, מגע ודמיון מודרך להתמודדות עם צירים.', 21),
('topic', 'flower', 'תנוחות ותנועה', 'תנוחות שמקדמות את הלידה ומקלות על הכאב, עם ובלי כדור פיזיו.', 22),
('topic', 'shield', 'שיכוך כאבים', 'אפידורל, גז צחוק ושיטות טבעיות – יתרונות, חסרונות ואיך לבחור.', 23),
('topic', 'users', 'תפקיד המלווה', 'איך בן/בת הזוג יכולים לתמוך באמת – בבית ובחדר הלידה.', 24),
('topic', 'baby', 'אחרי הלידה', 'השעות הראשונות, הנקה, התאוששות ושבועות ראשונים בבית.', 25),
('faq', null, 'מתי כדאי להתחיל קורס הכנה ללידה?', 'הזמן המומלץ הוא בין השבוע ה-28 לשבוע ה-34, כך שהחומר טרי ועדיין יש זמן לתרגל.', 30),
('faq', null, 'האם בן/בת הזוג יכולים להשתתף?', 'בהחלט, ואף מומלץ. חלק מהמפגשים מוקדשים במיוחד לתפקיד המלווה.', 31),
('faq', null, 'מה ההבדל בין דולה למיילדת?', 'המיילדת אחראית על ההיבט הרפואי של הלידה. הדולה מעניקה תמיכה רגשית ופיזית רציפה, ואינה מבצעת פעולות רפואיות.', 32),
('faq', null, 'איך ניגשים לתכנים באתר?', 'נרשמים באזור ההרשמה, משלמים בדף תשלום מאובטח, ומאותו רגע נכנסים עם המייל והסיסמה לאזור התכנים.', 33);
insert into public.course_lessons (module, title, summary, body, sort_order) values
('פרק 1 – לקראת הלידה', 'ברוכה הבאה לקורס', 'איך הקורס בנוי ואיך להפיק ממנו את המרב.', E'## ברוכה הבאה!\n\nבקורס הזה נלמד יחד מה קורה בגוף בזמן הלידה, איך להתמודד עם צירים ואיך להתכונן לימים הראשונים.', 1),
('פרק 1 – לקראת הלידה', 'סימנים לתחילת לידה', 'צירים מוקדמים, ירידת מים ומתי לנסוע.', null, 2),
('פרק 2 – התמודדות עם צירים', 'נשימות לכל שלב', 'תרגול מודרך של שלוש טכניקות נשימה.', null, 3),
('פרק 2 – התמודדות עם צירים', 'תנוחות ותנועה', 'תנוחות שמקלות על הכאב ומקדמות את הלידה.', null, 4),
('פרק 3 – אחרי הלידה', 'השעה הראשונה והנקה', 'מגע עור לעור, הנקה ראשונה והתאוששות.', null, 5);
